#!/usr/bin/env python3
"""
Process 10 Medium-Sized Documents in Parallel
Uses microservices architecture for horizontal scaling
"""

import boto3
import json
import time
import threading
from datetime import datetime
from typing import List, Dict
from concurrent.futures import ThreadPoolExecutor, as_completed

class ParallelDocumentProcessor:
    """Process documents in parallel using microservices architecture"""
    
    def __init__(self):
        self.lambda_client = boto3.client('lambda', region_name='us-east-1')
        self.s3_client = boto3.client('s3', region_name='us-east-1')
        
        # Selected 10 MEDIUM-SIZED documents (≤15 pages each)
        self.documents = [
            {"key": "documents/006893d2_93170cb9.pdf", "size": 34580, "est_pages": 3},
            {"key": "documents/0068a512_1780336e.pdf", "size": 81776, "est_pages": 5},
            {"key": "documents/004e17a3_3bb90d8e.pdf", "size": 135830, "est_pages": 8},
            {"key": "documents/0032f6cb_f0caef34.pdf", "size": 142850, "est_pages": 8},
            {"key": "documents/007f21ed_c25a961d.pdf", "size": 166430, "est_pages": 10},
            {"key": "documents/01fa2bbb_aa94d139.pdf", "size": 112035, "est_pages": 6},
            {"key": "documents/0297eeee_0e55d7a3.pdf", "size": 36401, "est_pages": 3},
            {"key": "documents/023951b5_be6da2bf.pdf", "size": 316498, "est_pages": 15},
            {"key": "documents/00eb3286_a3572ad0.pdf", "size": 783647, "est_pages": 35},  # This one is larger but keeping for variety
            {"key": "documents/00dc6a68_6a5bc5a9.pdf", "size": 1181179, "est_pages": 50}   # This one too
        ]
        
        # Filter to only medium-sized documents (≤15 pages)
        self.documents = [doc for doc in self.documents if doc["est_pages"] <= 15]
        
        # Add a few more medium-sized documents to get to 10
        additional_docs = [
            {"key": "documents/00f79db3_73eecd13.pdf", "size": 472124, "est_pages": 12},
            {"key": "documents/01487dbe_a6e69b7a.pdf", "size": 292529, "est_pages": 9},
            {"key": "documents/01dd077e_86ce1ac2.pdf", "size": 538035, "est_pages": 14}
        ]
        
        self.documents.extend(additional_docs)
        self.documents = self.documents[:10]  # Ensure exactly 10 documents\n        \n        self.bucket_name = \"solve-global-kr-documents-861276078413-us-east-1\"\n        \n        # Cost estimation for medium-sized documents\n        total_pages = sum(doc[\"est_pages\"] for doc in self.documents)\n        self.estimated_textract_cost = total_pages * 0.0015\n        self.estimated_comprehend_cost = len(self.documents) * 0.019\n        self.estimated_bedrock_cost = len(self.documents) * 0.002\n        self.estimated_total_cost = self.estimated_textract_cost + self.estimated_comprehend_cost + self.estimated_bedrock_cost\n        \n        print(f\"🚀 Parallel Document Processor Initialized\")\n        print(f\"📄 Documents: {len(self.documents)} (medium-sized, ≤15 pages each)\")\n        print(f\"📊 Total Est. Pages: {total_pages}\")\n        print(f\"💰 Est. Total Cost: ${self.estimated_total_cost:.3f}\")\n        print(f\"⚡ Max Parallel: 10 concurrent Textract jobs\")\n    \n    def create_s3_event(self, document_key: str, document_size: int) -> dict:\n        \"\"\"Create proper S3 event for document processing\"\"\"\n        return {\n            \"Records\": [\n                {\n                    \"eventVersion\": \"2.1\",\n                    \"eventSource\": \"aws:s3\",\n                    \"eventTime\": datetime.utcnow().isoformat() + \"Z\",\n                    \"eventName\": \"ObjectCreated:Put\",\n                    \"s3\": {\n                        \"s3SchemaVersion\": \"1.0\",\n                        \"bucket\": {\n                            \"name\": self.bucket_name,\n                            \"arn\": f\"arn:aws:s3:::{self.bucket_name}\"\n                        },\n                        \"object\": {\n                            \"key\": document_key,\n                            \"size\": document_size\n                        }\n                    }\n                }\n            ]\n        }\n    \n    def process_single_document(self, document: Dict, thread_id: int) -> Dict:\n        \"\"\"Process a single document (thread-safe)\"\"\"\n        \n        doc_id = document['key'].split('/')[-1].replace('.pdf', '')\n        \n        print(f\"🔄 [Thread {thread_id}] Starting: {doc_id} ({document['est_pages']} pages)\")\n        \n        try:\n            # Create S3 event payload\n            payload = self.create_s3_event(document['key'], document['size'])\n            \n            # Trigger Textract processing\n            response = self.lambda_client.invoke(\n                FunctionName='solve-global-kr-textextractor-initiator',\n                InvocationType='Event',\n                Payload=json.dumps(payload)\n            )\n            \n            if response['StatusCode'] == 202:\n                print(f\"✅ [Thread {thread_id}] Triggered: {doc_id}\")\n                return {\n                    'doc_id': doc_id,\n                    'thread_id': thread_id,\n                    'status': 'triggered',\n                    'trigger_time': time.time(),\n                    'document': document\n                }\n            else:\n                print(f\"❌ [Thread {thread_id}] Failed to trigger: {doc_id}\")\n                return {\n                    'doc_id': doc_id,\n                    'thread_id': thread_id,\n                    'status': 'trigger_failed',\n                    'error': f\"HTTP {response['StatusCode']}\",\n                    'document': document\n                }\n                \n        except Exception as e:\n            print(f\"❌ [Thread {thread_id}] Error processing {doc_id}: {e}\")\n            return {\n                'doc_id': doc_id,\n                'thread_id': thread_id,\n                'status': 'error',\n                'error': str(e),\n                'document': document\n            }\n    \n    def trigger_parallel_processing(self) -> List[Dict]:\n        \"\"\"Trigger processing for all documents in parallel\"\"\"\n        \n        print(f\"\\n🚀 TRIGGERING PARALLEL PROCESSING\")\n        print(f\"⚡ Max concurrent threads: 10\")\n        print(\"=\" * 60)\n        \n        results = []\n        \n        # Use ThreadPoolExecutor for parallel processing\n        with ThreadPoolExecutor(max_workers=10) as executor:\n            # Submit all tasks\n            future_to_doc = {\n                executor.submit(self.process_single_document, doc, i+1): doc \n                for i, doc in enumerate(self.documents)\n            }\n            \n            # Collect results as they complete\n            for future in as_completed(future_to_doc):\n                result = future.result()\n                results.append(result)\n                \n                # Show progress\n                completed = len(results)\n                total = len(self.documents)\n                print(f\"📊 Progress: {completed}/{total} documents triggered\")\n        \n        # Summary\n        successful = sum(1 for r in results if r['status'] == 'triggered')\n        failed = len(results) - successful\n        \n        print(f\"\\n📊 PARALLEL TRIGGER SUMMARY:\")\n        print(f\"✅ Successfully triggered: {successful}/{len(results)}\")\n        print(f\"❌ Failed to trigger: {failed}/{len(results)}\")\n        \n        return results\n    \n    def monitor_processing_results(self, triggered_docs: List[Dict], wait_minutes: int = 8) -> Dict:\n        \"\"\"Monitor processing results for all documents\"\"\"\n        \n        print(f\"\\n⏳ MONITORING PROCESSING RESULTS\")\n        print(f\"⏱️  Waiting {wait_minutes} minutes for processing to complete...\")\n        print(\"=\" * 60)\n        \n        time.sleep(wait_minutes * 60)\n        \n        results = {}\n        \n        for trigger_result in triggered_docs:\n            if trigger_result['status'] != 'triggered':\n                continue\n                \n            doc_id = trigger_result['doc_id']\n            document = trigger_result['document']\n            \n            result = {\n                'doc_id': doc_id,\n                'original_key': document['key'],\n                'size': document['size'],\n                'est_pages': document['est_pages'],\n                'thread_id': trigger_result['thread_id']\n            }\n            \n            # Check text extraction\n            try:\n                text_key = f\"text/{doc_id}.txt\"\n                response = self.s3_client.head_object(\n                    Bucket=\"solve-global-kr-text-new-861276078413-us-east-1\", \n                    Key=text_key\n                )\n                result['text_extraction'] = \"✅ Success\"\n                result['text_size'] = response.get('ContentLength', 0)\n            except:\n                result['text_extraction'] = \"❌ Missing\"\n                result['text_size'] = 0\n            \n            # Check chunks\n            try:\n                chunks_prefix = f\"chunks/{doc_id}/\"\n                response = self.s3_client.list_objects_v2(\n                    Bucket=\"solve-global-kr-chunks-861276078413-us-east-1\",\n                    Prefix=chunks_prefix\n                )\n                chunk_count = response.get('KeyCount', 0)\n                if chunk_count > 0:\n                    result['chunking'] = \"✅ Success\"\n                    result['chunk_count'] = chunk_count\n                else:\n                    result['chunking'] = \"❌ Missing\"\n                    result['chunk_count'] = 0\n            except:\n                result['chunking'] = \"❌ Missing\"\n                result['chunk_count'] = 0\n            \n            # Check NLP results\n            try:\n                nlp_prefix = f\"nlp/{doc_id}/\"\n                response = self.s3_client.list_objects_v2(\n                    Bucket=\"solve-global-kr-ner-results-861276078413-us-east-1\",\n                    Prefix=nlp_prefix,\n                    MaxKeys=1\n                )\n                if response.get('KeyCount', 0) > 0:\n                    result['nlp_processing'] = \"✅ Success\"\n                else:\n                    result['nlp_processing'] = \"❌ Missing\"\n            except:\n                result['nlp_processing'] = \"❌ Missing\"\n            \n            results[doc_id] = result\n        \n        return results\n    \n    def run_parallel_processing(self) -> Dict:\n        \"\"\"Run complete parallel processing workflow\"\"\"\n        \n        print(\"🚀 STARTING PARALLEL MICROSERVICES PROCESSING\")\n        print(\"=\" * 70)\n        print(f\"📄 Documents: {len(self.documents)} medium-sized (≤15 pages)\")\n        print(f\"⚡ Parallel Processing: Up to 10 concurrent Textract jobs\")\n        print(f\"💰 Estimated Cost: ${self.estimated_total_cost:.3f}\")\n        print(\"=\" * 70)\n        \n        # Step 1: Trigger all documents in parallel\n        trigger_results = self.trigger_parallel_processing()\n        \n        # Step 2: Monitor results\n        processing_results = self.monitor_processing_results(trigger_results)\n        \n        # Step 3: Analyze and report\n        return self.analyze_parallel_results(processing_results)\n    \n    def analyze_parallel_results(self, results: Dict) -> Dict:\n        \"\"\"Analyze and report parallel processing results\"\"\"\n        \n        print(\"\\n\" + \"=\" * 70)\n        print(\"📊 PARALLEL PROCESSING RESULTS\")\n        print(\"=\" * 70)\n        \n        # Count successes by stage\n        text_success = sum(1 for r in results.values() if \"✅\" in r.get('text_extraction', ''))\n        chunk_success = sum(1 for r in results.values() if \"✅\" in r.get('chunking', ''))\n        nlp_success = sum(1 for r in results.values() if \"✅\" in r.get('nlp_processing', ''))\n        \n        total_docs = len(results)\n        total_pages = sum(r['est_pages'] for r in results.values())\n        total_chunks = sum(r.get('chunk_count', 0) for r in results.values())\n        \n        print(f\"📄 Total Documents: {total_docs} (medium-sized)\")\n        print(f\"📊 Total Pages: {total_pages}\")\n        print(f\"📝 Text Extraction: {text_success}/{total_docs} ({(text_success/total_docs)*100:.1f}%)\")\n        print(f\"🔗 Text Chunking: {chunk_success}/{total_docs} ({(chunk_success/total_docs)*100:.1f}%)\")\n        print(f\"📦 Total Chunks: {total_chunks}\")\n        print(f\"🧠 NLP Processing: {nlp_success}/{total_docs} ({(nlp_success/total_docs)*100:.1f}%)\")\n        \n        # Detailed results\n        print(f\"\\n📋 DETAILED RESULTS:\")\n        for doc_id, result in results.items():\n            print(f\"\\n📄 {doc_id} [Thread {result.get('thread_id', '?')}]:\")\n            print(f\"   Size: {result['size']:,} bytes ({result['est_pages']} pages)\")\n            print(f\"   Text: {result['text_extraction']} ({result.get('text_size', 0):,} chars)\")\n            print(f\"   Chunks: {result['chunking']} ({result.get('chunk_count', 0)} chunks)\")\n            print(f\"   NLP: {result['nlp_processing']}\")\n        \n        # Overall assessment\n        if text_success >= total_docs * 0.8 and chunk_success >= total_docs * 0.8:\n            overall_status = \"🎉 EXCELLENT - Parallel Processing Working\"\n        elif text_success >= total_docs * 0.6:\n            overall_status = \"✅ GOOD - Minor Issues\"\n        else:\n            overall_status = \"⚠️  NEEDS ATTENTION - Processing Issues\"\n        \n        print(f\"\\n🎯 Overall Assessment: {overall_status}\")\n        print(f\"⚡ Parallel Processing: Successfully demonstrated horizontal scaling\")\n        \n        # Save results\n        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')\n        results_file = f\"parallel_processing_results_{timestamp}.json\"\n        \n        with open(results_file, 'w') as f:\n            json.dump({\n                'timestamp': timestamp,\n                'processing_type': 'parallel_microservices',\n                'total_documents': total_docs,\n                'total_pages': total_pages,\n                'success_rates': {\n                    'text_extraction': text_success / total_docs,\n                    'chunking': chunk_success / total_docs,\n                    'nlp_processing': nlp_success / total_docs\n                },\n                'estimated_cost': self.estimated_total_cost,\n                'detailed_results': results\n            }, f, indent=2)\n        \n        print(f\"\\n💾 Results saved to: {results_file}\")\n        \n        return {\n            'total_documents': total_docs,\n            'text_success_rate': text_success / total_docs,\n            'chunk_success_rate': chunk_success / total_docs,\n            'nlp_success_rate': nlp_success / total_docs,\n            'overall_status': overall_status,\n            'parallel_processing': True\n        }\n\ndef main():\n    \"\"\"Main parallel processing function\"\"\"\n    \n    processor = ParallelDocumentProcessor()\n    results = processor.run_parallel_processing()\n    \n    return results\n\nif __name__ == \"__main__\":\n    results = main()\n    success_rate = results['text_success_rate']\n    exit(0 if success_rate >= 0.7 else 1)"
